from django.core.files.storage import default_storage
from django.db import migrations


def discard_full_files(apps, schema_editor):
    """Apaga os áudios completos e, dos vídeos prontos, o vídeo enviado: ficam só os segmentos."""
    MediaSource = apps.get_model("videos", "MediaSource")
    for media in MediaSource.objects.all():
        names = [media.audio_original.name, media.audio_clean.name]
        if media.status == "ready":
            names.append(media.original.name)
            media.original = ""
            media.save(update_fields=["original"])
        for name in filter(None, names):
            default_storage.delete(name)


